import React, { useEffect, useState } from "react";
import axios from "axios";
import Layout from "./Layout";
import Notification from "./Notifications";
import { BrowserRouter, Routes, Route, Link } from "react-router-dom";
import About from "./About";
import videoFile from "./video.mp4";
import { motion }from "framer-motion";
import News from "./News";


// For Carousel
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";
import Slider from "react-slick";

// Import images correctly
import images1 from "./yourImage1.jpeg";
import images2 from "./yourImage2.jpeg";
import images3 from "./yourImage3.jpeg";
import nature from "./yourImage3.jpeg";



const App = () => {
  const [newsList, setNewsList] = useState([]);
  const [form, setForm] = useState({
    title: "",
    description: "",
    publishedDate: "",
  });
  const [query, setQuery] = useState("");

  useEffect(() => {
    fetchNews();
  }, []);

  const fetchNews = async () => {
    try {
      const res = await axios.get("http://localhost:8080/api/news");
      setNewsList(res.data);
    } catch (err) {
      console.error("Error fetching news:", err);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await axios.post("http://localhost:8080/api/news", form);
      setForm({ title: "", description: "", publishedDate: "" });
      fetchNews();
    } catch (err) {
      console.error("Error adding news:", err);
    }
  };

  const handleDelete = async (id) => {
    try {
      await axios.delete(`http://localhost:8080/api/news/${id}`);
      fetchNews();
    } catch (err) {
      console.error("Error deleting news:", err);
    }
  };

  const handleSearch = async () => {
    if (!query.trim()) {
      fetchNews();
      return;
    }
    try {
      const res = await axios.get(
        `http://localhost:8080/api/news/search?query=${encodeURIComponent(
          query
        )}`
      );
      setNewsList(res.data);
    } catch (err) {
      console.error("Error searching news:", err);
    }
  };

  return (
    <div>
      {/* Full-screen video with menu */}
      <div
        style={{
          position: "relative",
          width: "100vw",
          height: "100vh",
          overflow: "hidden",
        }}
      >
        <video
          src={videoFile}
          autoPlay
          loop
          muted
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            objectFit: "cover",
            zIndex: 1,
          }}
        />
        {/* Custom Menu */}
        <nav
          style={{
            position: "absolute",
            top: "20px",
            right: "40px",
            display: "flex",
            gap: "30px",
            zIndex: 2,
            fontFamily: "'Impact', sans-serif",
            fontSize: "22px",
            fontWeight: "bold",
          }}
        >
          <a href="#news" style={{ color: "white", textDecoration: "none" }}>
            LATEST NEWS
          </a>
          <a href="#signin" style={{ color: "white", textDecoration: "none" }}>
            SIGN IN
          </a>
          <a href="#about" style={{ color: "white", textDecoration: "none" }}>
            ABOUT
          </a>
        </nav>
      </div>

      {/* Three cards section below video */}
      <div
        style={{
          display: "flex",
          justifyContent: "center",
          gap: "20px",
          flexWrap: "wrap",
          padding: "50px 20px",
          backgroundColor: "#f0f0f0",
        }}
      >
        {/* Card 1 */}
        <div
          style={{
            border: "2px solid white",
            borderRadius: "10px",
            padding: "20px",
            textAlign: "center",
            width: "300px",
            backgroundColor: "#ffffff",
            boxShadow: "0 4px 8px rgba(0,0,0,0.5)",
          }}
        >
          <img
            src={images1}
            alt="Card Image 1"
            style={{
              width: "100%",
              height: "auto",
              borderRadius: "5px",
              marginBottom: "15px",
            }}
          />
          <h3>AI Industry Sees Record Investment</h3>
          <p>
            The artificial intelligence sector attracted unprecedented funding
            this year, with venture capital firms investing billions in AI
            startups.
          </p>
        </div>

        {/* Card 2 */}
        <div
          style={{
            border: "2px solid white",
            borderRadius: "10px",
            padding: "20px",
            textAlign: "center",
            width: "300px",
            backgroundColor: "#ffffff",
            boxShadow: "0 4px 8px rgba(0,0,0,0.5)",
          }}
        >
          <img
            src={images2}
            alt="Card Image 2"
            style={{
              width: "100%",
              height: "auto",
              borderRadius: "5px",
              marginBottom: "15px",
            }}
          />
          <h3>Google Chrome</h3>
          <p>
            Google Chrome gets 10 new AI features, including smarter browsing,
            recall and more.
          </p>
